@yusukebe Thank you for your pointed out.

I see, that's right! I got the same result in my environment. I didn't think there would be a difference with `.at(-1)`, but there definitely is a difference in the benchmark.

<details>

<summary>bench mark various pattern</summary>

```ts
import { run, bench, group } from 'mitata'

export const mergePathNew: (...paths: string[]) => string = (
  base: string | undefined,
  sub: string | undefined,
  ...rest: string[]
): string => {
  if (rest.length) {
    sub = mergePathNew(sub as string, ...rest)
  }
  return `${base?.[0] === '/' ? '' : '/'}${base}${
    sub === '/' ? '' : `${base?.at(-1) === '/' ? '' : '/'}${sub?.[0] === '/' ? sub.slice(1) : sub}`
  }`
}

export const mergePathWithLength: (...paths: string[]) => string = (
  base: string | undefined,
  sub: string | undefined,
  ...rest: string[]
): string => {
  if (rest.length) {
    sub = mergePathNew(sub as string, ...rest)
  }
  return `${base?.[0] === '/' ? '' : '/'}${base}${
    sub === '/'
      ? ''
      : `${base?.[base.length - 1] === '/' ? '' : '/'}${sub?.[0] === '/' ? sub.slice(1) : sub}`
  }`
}

export const mergePathWithMethod: (...paths: string[]) => string = (
  base: string | undefined,
  sub: string | undefined,
  ...rest: string[]
): string => {
  if (rest.length) {
    sub = mergePathNew(sub as string, ...rest)
  }
  return `${base?.startsWith('/') ? '' : '/'}${base}${
    sub === '/' ? '' : `${base?.endsWith('/') ? '' : '/'}${sub?.[0] === '/' ? sub.slice(1) : sub}`
  }`
}

export const mergePath = (...paths: string[]): string => {
  let p: string = ''
  let endsWithSlash = false

  for (let path of paths) {
    // calculate endsWithSlash at the start of each iteration
    endsWithSlash = p.at(-1) === '/'

    /* ['/hey/','/say'] => ['/hey', '/say'] */
    if (endsWithSlash) {
      p = p.slice(0, -1)
    }

    /* ['/hey','say'] => ['/hey', '/say'] */
    if (path[0] !== '/') {
      path = `/${path}`
    }

    /* ['/hey/', '/'] => `/hey/` */
    if (path === '/' && endsWithSlash) {
      p = `${p}/`
    } else if (path !== '/') {
      p = `${p}${path}`
    }

    /* ['/', '/'] => `/` */
    if (path === '/' && p === '') {
      p = '/'
    }
  }

  return p
}

bench('noop', () => {})

group('two paths', () => {
  bench('mergePath', () => mergePath('/api', '/users'))
  bench('mergePathNew', () => mergePathNew('/api', '/users'))
  bench('mergePathWithLength', () => mergePathWithLength('/api', '/users'))
  bench('mergePathWithMethod', () => mergePathWithMethod('/api', '/users'))
})

group('three paths', () => {
  bench('mergePath', () => mergePath('/api', '/users', '/books'))
  bench('mergePathNew', () => mergePathNew('/api', '/users', '/books'))
  bench('mergePathWithLength', () => mergePathWithLength('/api', '/users', '/books'))
  bench('mergePathWithMethod', () => mergePathWithMethod('/api', '/users', '/books'))
})

group('four paths', () => {
  bench('mergePath', () => mergePath('/api', '/users', '/books', 'abc'))
  bench('mergePathNew', () => mergePathNew('/api', '/users', '/books', 'abc'))
  bench('mergePathWithLength', () => mergePathWithLength('/api', '/users', '/books', 'abc'))
  bench('mergePathWithMethod', () => mergePathWithMethod('/api', '/users', '/books', 'abc'))
})

run()
```

